import * as THREE from 'three';

const D=window.GAME_DATA, $=id=>document.getElementById(id);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), lerp=(a,b,t)=>a+(b-a)*t, TAU=Math.PI*2;
const rndInt=(a,b)=>a+Math.floor(Math.random()*(b-a+1));
const angDiff=(a,b)=>{let d=a-b;return Math.atan2(Math.sin(d),Math.cos(d));};
const store={get(k,d){try{const v=localStorage.getItem(k);return v===null?d:JSON.parse(v);}catch(e){return d;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){}},del(k){try{localStorage.removeItem(k);}catch(e){}}};
function mulberry32(seed){let a=seed|0;return function(){a=(a+0x6D2B79F5)|0;let t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}

const SAVE_KEY='fortress_save_v1';
const XP_TABLE=[0,60,160,320,560,900,1400,2100,3000];
const WORLD_R=100,SAFE_R=118,GATHER_DUR=.55,MAX_DROPS=120,MAX_YIELD=6,BASE_CAP=60,CAP_PER_LVL=8;
const DODGE_COST=16,DODGE_DUR=.28,DODGE_CD=.7,MAX_ENEMIES=40,MAX_BULLETS=120;
const STR=D.strategic;

function freshState(){return{hp:100,stamina:100,coins:30,xp:0,level:1,inventory:{club:1},equipment:{tool:null,weapon:'club',gun:null,armor:null,charm:null},buffs:{luck:0,power:0,defense:0},location:'fortress',visited:{fortress:true},tutorialStep:0,tutorialDone:false,counters:{gather:{},sold:{},bought:{},clears:0},poison:0,playTime:0,score:0,strat:null};}
let S=freshState();const saved=store.get(SAVE_KEY,null);const hasSave=!!saved;if(saved)S=Object.assign(freshState(),saved);
const ITEMS=D.items,RAR=D.rarities,CAT=D.categories;
function item(id){return ITEMS[id];}
function ensureCounters(){if(!S.counters)S.counters={gather:{},sold:{},bought:{},clears:0};['gather','sold','bought'].forEach(k=>{if(!S.counters[k])S.counters[k]={};});if(typeof S.counters.clears!=='number')S.counters.clears=0;}
function initStrat(){if(S.strat&&S.strat.pops)return;S.strat={pops:{},fortressHP:STR.fortressMaxHP,migrateT:STR.migrateEvery,regrowT:STR.regrowEvery,raidCountdown:-1,raidActive:false,raidLeft:0,migrations:[]};STR.ring.forEach(id=>S.strat.pops[id]=D.locations[id].startPop||4);}
function normalizeState(){const f=freshState();S.inventory=S.inventory||{};S.equipment=Object.assign(f.equipment,S.equipment||{});S.buffs=Object.assign(f.buffs,S.buffs||{});S.visited=Object.assign(f.visited,S.visited||{});ensureCounters();initStrat();if(typeof S.tutorialStep!=='number')S.tutorialStep=0;if(typeof S.tutorialDone!=='boolean')S.tutorialDone=false;if(!D.locations[S.location])S.location='fortress';['hp','stamina','coins','xp','level','poison','playTime','score'].forEach(k=>{if(typeof S[k]!=='number')S[k]=f[k];});if(!S.equipment.weapon||!item(S.equipment.weapon))S.equipment.weapon='club';}
normalizeState();

let world=null,state='intro',activePanel='intro',selectedMap='fortress',tradeTab='buy',selectedInv=null,craftFilter='all',invFilter='all';
let toastTimer=null,saveTimer=0,hudTimer=0,interactQueued=false,jumpQueued=false,dodgeQueued=false,sprintTouch=false,meleeHeld=false,gunHeld=false;
let fireCd=0,dayTime=.35,nearestInteract=null,shake=0,hitstop=0,uiDirty=true,lastPrompt='',travelWatchdog=null,errCount=0,harvestTimes=[],fullNoticeT=0;
let scoreMult=1,multT=0;
const keys={},joy={x:0,y:0,id:null};let mouseX=innerWidth/2,mouseY=innerHeight/2,aimX=0,aimZ=0;
const player={x:0,y:0,z:5,vx:0,vz:0,vy:0,grounded:true,facing:Math.PI,walkPhase:0,prevSin:0,landT:0,moving:false,sprinting:false,invuln:0,dodgeT:0,dodgeCd:0,dodgeVX:0,dodgeVZ:1,gatherT:0,gatherTarget:null,gatherDone:false,meleeT:0,meleeDur:.4,meleeHit:false,combo:0,comboT:0,recoilT:0};

function rarityColor(id){return RAR[item(id).rarity].color;}
function catMeta(id){return CAT[item(id).cat]||CAT.resource;}
function catBadge(id){const c=catMeta(id);return`<span class="cat-badge" style="color:${c.color};border-color:${c.color}66;background:${c.color}14">${c.icon} ${c.name}</span>`;}
function count(id){return S.inventory[id]||0;}
function weightOf(id,n=1){return(item(id)?.weight||0)*n;}
function currentWeight(){let w=0;for(const id in S.inventory)w+=weightOf(id,count(id));return Math.round(w*10)/10;}
function capacity(){let c=BASE_CAP+(S.level-1)*CAP_PER_LVL;for(const sl in S.equipment){const id=S.equipment[sl];if(id&&item(id)&&item(id).capacity)c+=item(id).capacity;}return c;}
function canPickup(id,n=1){return currentWeight()+weightOf(id,n)<=capacity()+1e-6;}
function addItem(id,n=1){if(!item(id))return;S.inventory[id]=count(id)+n;uiDirty=true;}
function takeItem(id,n=1){if(count(id)<n)return false;S.inventory[id]-=n;if(S.inventory[id]<=0)delete S.inventory[id];uiDirty=true;return true;}
function currentGun(){const it=item(S.equipment.gun);return(it&&it.gun)?it.gun:null;}
function currentMelee(){const it=item(S.equipment.weapon);return(it&&it.slot==='weapon')?it:{atk:5,reach:2.2,speed:.4,name:'Кулаки'};}
function stats(){const s={atk:2,def:0,gatherType:null,gatherPower:0,speed:0,luck:0,maxHp:100+(S.level-1)*12,maxStamina:100+(S.level-1)*6,poisonResist:0};for(const sl in S.equipment){const id=S.equipment[sl];if(!id)continue;const it=item(id);if(!it)continue;for(const k of['atk','def','speed','luck','maxStamina','poisonResist'])s[k]+=it[k]||0;if(it.slot==='tool'){s.gatherType=it.gatherType;s.gatherPower=it.gatherPower||1;}}if(S.buffs.power>0)s.atk+=S.buffs.power;if(S.buffs.defense>0)s.def+=S.buffs.defense;if(S.buffs.luck>0)s.luck+=S.buffs.luck;return s;}
function equipItem(id){const it=item(id);if(!it||!it.slot||count(id)<=0)return;const old=S.equipment[it.slot];takeItem(id,1);if(old)addItem(old,1);S.equipment[it.slot]=id;toast('Экипировано: '+it.name);updateGunVisual();uiDirty=true;checkTutorial();save();}
function unequip(slot){const id=S.equipment[slot];if(!id)return;S.equipment[slot]=null;addItem(id,1);updateGunVisual();uiDirty=true;save();}
function addXP(n){S.xp+=n;let lvl=1;for(let i=0;i<XP_TABLE.length;i++)if(S.xp>=XP_TABLE[i])lvl=i+1;if(lvl>S.level){S.level=lvl;S.hp=stats().maxHp;toast('⭐ Уровень '+lvl+'!');Sfx.level();uiDirty=true;}}
function useItem(id){const it=item(id);if(!it||!it.use||!takeItem(id,1))return;const st=stats();if(it.use.heal)S.hp=clamp(S.hp+it.use.heal,0,st.maxHp);if(it.use.stamina)S.stamina=clamp(S.stamina+it.use.stamina,0,st.maxStamina);if(it.use.curePoison)S.poison=0;Sfx.eat();toast('Использовано: '+it.name);uiDirty=true;}
function sellPrice(id){return Math.max(1,Math.floor(item(id).value*.6));}
function buyPrice(id){return Math.ceil(item(id).value*2.5);}
function fullNotice(){const now=performance.now();if(now-fullNoticeT<2500)return;fullNoticeT=now;toast('🎒 Рюкзак полон!');Sfx.deny();}

