const QUAL={high:{pixel:2,shadow:true,grass:1000,flowers:240,decor:260,rocks:140,enemies:40},medium:{pixel:1.5,shadow:true,grass:600,flowers:140,decor:150,rocks:80,enemies:30},low:{pixel:1,shadow:false,grass:260,flowers:60,decor:70,rocks:40,enemies:20}};

const Sfx={ctx:null,master:null,muted:store.get('fortress_muted',false),
ensure(){if(!this.ctx){try{const AC=window.AudioContext||window.webkitAudioContext;this.ctx=new AC();this.master=this.ctx.createGain();this.master.gain.value=this.muted?0:.7;this.master.connect(this.ctx.destination);}catch(e){}}if(this.ctx&&this.ctx.state==='suspended')this.ctx.resume();},
setMuted(m){this.muted=m;store.set('fortress_muted',m);if(this.master&&this.ctx)this.master.gain.linearRampToValueAtTime(m?0:.7,this.ctx.currentTime+.1);$('icoSoundOn').style.display=m?'none':'';$('icoSoundOff').style.display=m?'':'none';},
tone(f0,f1,dur,type,vol){if(!this.ctx||this.muted)return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(Math.max(f1,1),t+dur);g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+dur+.02);},
noise(dur,freq,vol){if(!this.ctx||this.muted)return;const len=Math.floor(this.ctx.sampleRate*dur),buf=this.ctx.createBuffer(1,len,this.ctx.sampleRate),d=buf.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);const s=this.ctx.createBufferSource();s.buffer=buf;const f=this.ctx.createBiquadFilter();f.type='lowpass';f.frequency.value=freq;const g=this.ctx.createGain();g.gain.value=vol;s.connect(f);f.connect(g);g.connect(this.master);s.start();},
step(){this.noise(.03,700,.05);},jump(){this.tone(260,520,.12,'triangle',.14);},land(){this.noise(.08,300,.2);},interact(){this.tone(420,640,.1,'sine',.13);},pickup(){this.tone(620,920,.12,'sine',.16);},eat(){this.noise(.07,900,.12);},craft(){this.tone(300,600,.15,'square',.1);setTimeout(()=>this.tone(450,900,.15,'sine',.14),120);},coin(){this.tone(800,1200,.08,'sine',.14);},
swing(){this.noise(.08,1600,.12);this.tone(260,140,.08,'sine',.08);},meleeHit(){this.noise(.06,700,.18);this.tone(180,90,.09,'square',.1);},
shoot(){this.noise(.06,2400,.2);this.tone(340,110,.07,'square',.1);},shotgun(){this.noise(.14,1300,.28);this.tone(160,60,.14,'square',.14);},dry(){this.tone(200,150,.06,'square',.08);},
dodge(){this.noise(.12,900,.16);this.tone(420,180,.12,'sine',.1);},chop(){this.noise(.07,900,.2);this.tone(160,90,.1,'square',.1);},mine(){this.noise(.06,1400,.22);this.tone(240,120,.09,'square',.1);},cut(){this.noise(.05,2200,.14);},deny(){this.tone(180,120,.12,'square',.1);},hit(){this.noise(.06,600,.16);this.tone(200,100,.08,'sawtooth',.1);},kill(){this.tone(300,120,.14,'square',.12);this.noise(.1,900,.16);},hurt(){this.tone(200,70,.25,'sawtooth',.18);},level(){[523,659,784,1047].forEach((f,i)=>setTimeout(()=>this.tone(f,f,.2,'triangle',.18),i*100));},death(){[330,247,196].forEach((f,i)=>setTimeout(()=>this.tone(f,f*.9,.3,'triangle',.16),i*180));},travel(){this.tone(200,800,.5,'sine',.15);},raid(){this.tone(160,380,.4,'sawtooth',.16);setTimeout(()=>this.tone(200,460,.3,'sawtooth',.14),220);}};
Sfx.setMuted(Sfx.muted);

function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600);}
function lootFeed(html,color){const feed=$('lootFeed');const div=document.createElement('div');div.className='loot-line';div.style.borderColor=color||'var(--line)';div.style.color=color||'var(--text)';div.innerHTML=html;feed.appendChild(div);while(feed.children.length>5)feed.removeChild(feed.firstChild);setTimeout(()=>{if(div.parentNode)div.parentNode.removeChild(div);},3100);}
function save(){store.set(SAVE_KEY,S);}
function reportErr(err){console.error(err);errCount++;if(errCount===1)toast('⚠️ '+err.message);if(errCount>40){state='paused';openPanel('pause');}}

