function threat(){let total=0,max=0;STR.ring.forEach(id=>{total+=S.strat.pops[id]||0;max+=D.locations[id].maxPop;});return clamp(total/max*100,0,100);}
function renderHUD(){const st=stats();$('hpFill').style.width=clamp(S.hp/st.maxHp*100,0,100)+'%';$('stFill').style.width=clamp(S.stamina/st.maxStamina*100,0,100)+'%';$('hpText').textContent=Math.ceil(S.hp);$('stText').textContent=Math.ceil(S.stamina);$('lvlText').textContent='Ур.'+S.level;const cur=XP_TABLE[S.level-1]||0,next=XP_TABLE[S.level]||XP_TABLE[XP_TABLE.length-1];$('xpFill').style.width=clamp((S.xp-cur)/(next-cur)*100,0,100)+'%';$('coinText').textContent=S.coins;$('locText').textContent=D.locations[S.location].name;const w=currentWeight(),cap=capacity();$('capText').textContent=w.toFixed(1)+'/'+cap;$('capFill').style.width=clamp(w/cap*100,0,100)+'%';capChip.classList.toggle('full',w>=cap-.05);
const th=threat();$('threatFill').style.width=th+'%';$('fortFill').style.width=clamp(S.strat.fortressHP/STR.fortressMaxHP*100,0,100)+'%';const rw=$('raidWarn');if(S.strat.raidActive){rw.style.display='block';rw.textContent='🔥 НАБЕГ! Врагов: '+S.strat.raidLeft;}else if(S.strat.raidCountdown>0){rw.style.display='block';rw.textContent='⚠️ Набег через '+Math.ceil(S.strat.raidCountdown)+'с';}else rw.style.display='none';
$('meleeVal').textContent=currentMelee().name||'Кулаки';const g=currentGun();$('gunVal').textContent=g?(item(S.equipment.gun).name):'—';$('ammoVal').textContent=count('ammo');$('ammoVal').classList.toggle('empty',count('ammo')<=0);$('dodgeVal').textContent=player.dodgeCd>0?player.dodgeCd.toFixed(1)+'с':'Q';$('dodgeVal').style.color=player.dodgeCd>0?'var(--danger)':'var(--teal)';}
function counterKey(t){return t==='sell'?'sold':t==='buy'?'bought':'gather';}
function renderQuest(){ensureCounters();if(S.tutorialDone){$('questText').textContent='Зачищайте лагеря вокруг крепости. Если угроза растёт — будет набег.';$('questProgress').textContent='Уровень '+S.level+' · зачисток '+S.counters.clears;return;}const q=D.tutorial[S.tutorialStep];if(!q){$('questText').textContent='';$('questProgress').textContent='';return;}$('questText').textContent=q.text;let p='';if(q.type==='gather')p=Object.entries(q.need).map(([id,n])=>(S.counters.gather[id]||0)+'/'+n+' '+item(id).name).join(' · ');else if(q.type==='haveAny')p=q.need.some(id=>count(id)>0||S.equipment.weapon===id)?'Готово':'Создайте оружие';else if(q.type==='equipSlot')p=S.equipment[q.slot]?'Готово':'Не экипировано';else if(q.type==='travelAny')p=S.location!=='fortress'?'Готово':'Вы в крепости';else if(q.type==='clearAny')p=S.counters.clears>0?'Готово':'Зачистите лагерь';$('questProgress').textContent=p;}
function checkTutorial(){ensureCounters();if(S.tutorialDone)return;let guard=0;while(!S.tutorialDone&&guard++<20){const q=D.tutorial[S.tutorialStep];if(!q){S.tutorialDone=true;break;}let ok=false;if(q.type==='gather')ok=Object.entries(q.need).every(([id,n])=>(S.counters.gather[id]||0)>=n);else if(q.type==='haveAny')ok=q.need.some(id=>count(id)>0||S.equipment.weapon===id);else if(q.type==='equipSlot')ok=!!S.equipment[q.slot];else if(q.type==='travelAny')ok=S.location!=='fortress';else if(q.type==='clearAny')ok=S.counters.clears>0;if(!ok)break;S.tutorialStep++;Sfx.pickup();toast('✅ Цель выполнена!');if(S.tutorialStep>=D.tutorial.length){S.tutorialDone=true;toast('🎓 Обучение завершено!');}}uiDirty=true;}
function attrText(it){const names={atk:'Атака',def:'Защита',reach:'Дальность',speed:'Скорость',gatherType:'Инструмент',gatherPower:'Сила добычи',luck:'Удача'};const l=[];for(const k in names)if(it[k])l.push(names[k]+': '+it[k]);if(it.gun){const g=it.gun;l.push('Урон: '+g.dmg+' · Темп: '+g.rate+'/с · Патронов за выстрел: '+g.ammoCost);if(g.pellets>1)l.push('Дробь: '+g.pellets);if(g.pierce)l.push('Пробитие: '+g.pierce);}if(it.use){const u=[];if(it.use.heal)u.push('+'+it.use.heal+' HP');if(it.use.stamina)u.push('+'+it.use.stamina+' сил');if(it.use.curePoison)u.push('снимает яд');l.push(u.join(', '));}l.push('Ценность: '+it.value+' 🪙 · Вес: '+it.weight);return l.join('<br>');}
function buildFilters(){const cats=['all',...Object.keys(CAT)];const html=(cur,kind)=>cats.map(c=>`<button class="filter-btn ${cur===c?'active':''}" data-kind="${kind}" data-cat="${c}">${c==='all'?'Все':CAT[c].icon+' '+CAT[c].name}</button>`).join('');$('craftFilters').innerHTML=html(craftFilter,'craft');$('invFilters').innerHTML=html(invFilter,'inv');}
function renderInventory(){const st=stats(),w=currentWeight(),cap=capacity();$('statLine').innerHTML='⚔️ '+st.atk+' · 🛡️ '+st.def+' · 🍀 '+st.luck+'<br><span style="color:'+(w>=cap?'var(--danger)':'var(--teal)')+'">🎒 Вес: '+w.toFixed(1)+' / '+cap+'</span>';const sn={tool:'Инструмент',weapon:'Ближний бой',gun:'Огнестрел',armor:'Броня',charm:'Амулет'};$('equipSlots').innerHTML=Object.keys(S.equipment).map(slot=>{const id=S.equipment[slot];const it=id?item(id):null;return`<div class="equip-slot" data-slot="${slot}"><div class="es-label">${sn[slot]||slot}</div><div class="es-icon">${it?it.icon:'—'}</div><div class="es-name" style="color:${it?rarityColor(id):'var(--dim)'}">${it?it.name:'Пусто'}</div></div>`;}).join('');const ids=Object.keys(S.inventory).filter(id=>count(id)>0&&(invFilter==='all'||item(id).cat===invFilter)).sort((a,b)=>RAR[item(a).rarity].order-RAR[item(b).rarity].order);$('invGrid').innerHTML=ids.map(id=>{const it=item(id);return`<div class="inv-item" data-id="${id}" style="border-color:${rarityColor(id)}55"><div class="ii-count">×${count(id)}</div><div class="ii-icon">${it.icon}</div><div class="ii-name" style="color:${rarityColor(id)}">${it.name}</div><div class="ii-cat">${catBadge(id)}</div></div>`;}).join('')||'<div class="story">Пусто.</div>';renderInvDetail();}
function renderInvDetail(){const id=selectedInv,box=$('invDetail');if(!id||!item(id)||count(id)<=0){box.innerHTML='Выберите предмет.';return;}const it=item(id),cm=catMeta(id);let b='';if(it.slot)b+=`<button class="btn-primary" data-action="equip" data-id="${id}">Экипировать</button>`;if(it.use)b+=`<button class="btn-ghost" data-action="use" data-id="${id}">Использовать</button>`;if(it.value>0)b+=`<button class="btn-ghost" data-action="sell" data-id="${id}">Продать ${sellPrice(id)} 🪙</button>`;b+=`<button class="btn-ghost" data-action="drop" data-id="${id}">Выбросить</button>`;box.innerHTML=`<div class="id-name" style="color:${rarityColor(id)}">${it.icon} ${it.name} <span style="font-size:11px;color:var(--dim)">(${RAR[it.rarity].name})</span> ${catBadge(id)}</div><div class="id-purpose">📌 ${cm.purpose}</div><div class="id-desc">${it.desc}</div><div class="id-attrs">${attrText(it)}</div><div class="btn-row" style="justify-content:flex-start;margin-top:10px">${b}</div>`;}
function renderCraft(){const list=D.recipes.filter(r=>craftFilter==='all'||item(r.out).cat===craftFilter);$('craftList').innerHTML=list.map(r=>{const idx=D.recipes.indexOf(r);const it=item(r.out);const canL=S.level>=r.level;const mats=Object.entries(r.mats).map(([id,n])=>`<span class="${count(id)>=n?'ok':'missing'}">${item(id).icon}${count(id)}/${n}</span>`).join(' ');const can=canL&&Object.entries(r.mats).every(([id,n])=>count(id)>=n);return`<div class="recipe"><div class="r-icon">${it.icon}</div><div class="r-main"><div class="r-name" style="color:${rarityColor(r.out)}">${it.name} <span style="font-size:10px;color:var(--dim)">ур.${r.level}</span> ${catBadge(r.out)}</div><div class="r-mats">${mats}</div></div><button class="btn-ghost" data-idx="${idx}" ${can?'':'disabled'}>Создать</button></div>`;}).join('')||'<div class="story">Нет рецептов.</div>';}
function craft(idx){const r=D.recipes[idx];if(!r)return;if(S.level<r.level){toast('Нужен уровень '+r.level);return;}if(!Object.entries(r.mats).every(([id,n])=>count(id)>=n)){toast('Не хватает материалов');return;}Object.entries(r.mats).forEach(([id,n])=>takeItem(id,n));addItem(r.out,r.n||1);addXP(12+RAR[item(r.out).rarity].order*8);Sfx.craft();toast('🛠️ Создано: '+item(r.out).name);burst(player.x,1.4,player.z,0xffd166,16,3,3,.8);uiDirty=true;checkTutorial();save();}
