function makeTex(size,draw,repeat=1){const c=document.createElement('canvas');c.width=c.height=size;const g=c.getContext('2d');draw(g,size);const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(repeat,repeat);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=4;return t;}
function noiseFill(g,s,base,spots,dots){g.fillStyle=base;g.fillRect(0,0,s,s);for(let i=0;i<spots;i++){g.fillStyle=`rgba(0,0,0,${Math.random()*.12})`;const r=2+Math.random()*10;g.beginPath();g.arc(Math.random()*s,Math.random()*s,r,0,TAU);g.fill();}for(let i=0;i<dots;i++){g.fillStyle=`rgba(255,255,255,${Math.random()*.1})`;g.fillRect(Math.random()*s,Math.random()*s,1+Math.random()*2,1+Math.random()*2);}}
const TEX={};
TEX.grass=makeTex(256,(g,s)=>{noiseFill(g,s,'#4e9a55',160,900);for(let i=0;i<1400;i++){const x=Math.random()*s,y=Math.random()*s;g.strokeStyle=`rgba(${30+Math.random()*40},${110+Math.random()*70},${50+Math.random()*40},.5)`;g.lineWidth=1;g.beginPath();g.moveTo(x,y);g.lineTo(x+(Math.random()-.5)*3,y-3-Math.random()*4);g.stroke();}},48);
