TEX.leaf=makeTex(128,(g,s)=>{noiseFill(g,s,'#3f9a52',80,400);for(let i=0;i<220;i++){g.fillStyle=`rgba(${60+Math.random()*60},${150+Math.random()*70},${70+Math.random()*40},.5)`;g.beginPath();g.ellipse(Math.random()*s,Math.random()*s,2+Math.random()*4,1+Math.random()*2,Math.random()*TAU,0,TAU);g.fill();}},2);
TEX.rock=makeTex(128,(g,s)=>{noiseFill(g,s,'#8a9588',90,300);for(let i=0;i<26;i++){g.strokeStyle=`rgba(40,45,40,${.2+Math.random()*.3})`;g.lineWidth=1;g.beginPath();let x=Math.random()*s,y=Math.random()*s;g.moveTo(x,y);for(let k=0;k<4;k++){x+=(Math.random()-.5)*20;y+=(Math.random()-.5)*20;g.lineTo(x,y);}g.stroke();}},2);
TEX.stone=makeTex(128,(g,s)=>{noiseFill(g,s,'#9a9a90',60,200);g.strokeStyle='rgba(0,0,0,.18)';g.lineWidth=2;for(let y=0;y<s;y+=16){g.beginPath();g.moveTo(0,y);g.lineTo(s,y);g.stroke();for(let x=(y/16%2)*16;x<s;x+=32){g.beginPath();g.moveTo(x,y);g.lineTo(x,y+16);g.stroke();}}},3);
TEX.metal=makeTex(128,(g,s)=>{noiseFill(g,s,'#9aa0a8',40,300);for(let i=0;i<60;i++){g.strokeStyle=`rgba(255,255,255,${.05+Math.random()*.1})`;g.lineWidth=1;const y=Math.random()*s;g.beginPath();g.moveTo(0,y);g.lineTo(s,y+(Math.random()-.5)*4);g.stroke();}},1);
TEX.cloth=makeTex(128,(g,s)=>{noiseFill(g,s,'#c9c2b0',30,200);g.strokeStyle='rgba(0,0,0,.08)';g.lineWidth=1;for(let i=0;i<s;i+=4){g.beginPath();g.moveTo(i,0);g.lineTo(i,s);g.stroke();g.beginPath();g.moveTo(0,i);g.lineTo(s,i);g.stroke();}},2);
TEX.skin=makeTex(128,(g,s)=>{noiseFill(g,s,'#b0b0b0',70,300);for(let i=0;i<40;i++){g.fillStyle=`rgba(0,0,0,${.05+Math.random()*.1})`;g.beginPath();g.arc(Math.random()*s,Math.random()*s,1+Math.random()*3,0,TAU);g.fill();}},1);
TEX.bump=makeTex(128,(g,s)=>{g.fillStyle='#808080';g.fillRect(0,0,s,s);for(let i=0;i<2000;i++){const v=100+Math.random()*80;g.fillStyle=`rgb(${v},${v},${v})`;g.fillRect(Math.random()*s,Math.random()*s,1+Math.random()*2,1+Math.random()*2);}},4);
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=128;const g=c.getContext('2d');const r=g.createRadialGradient(64,64,2,64,64,62);r.addColorStop(0,'rgba(255,255,255,1)');r.addColorStop(.35,'rgba(255,255,255,.45)');r.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=r;g.fillRect(0,0,128,128);return new THREE.CanvasTexture(c);}
