function spawnDrop(itemId,x,y,z,n,source,pickupDelay=0){if(!item(itemId)||n<=0)return;const merge=world.drops.find(d=>!d.collected&&d.item===itemId&&d.source===source&&Math.hypot(d.x-x,d.z-z)<3.5);if(merge){merge.n+=n;merge.pickupDelay=Math.max(merge.pickupDelay||0,pickupDelay);return;}if(world.drops.length>=MAX_DROPS){const old=world.drops[0];if(old&&collectDrop(old)){world.group.remove(old.group);world.drops.shift();}else{const any=world.drops.find(d=>!d.collected&&d.item===itemId);if(any){any.n+=n;return;}}}const it=item(itemId),color=new THREE.Color(rarityColor(itemId));const g=new THREE.Group();const mesh=new THREE.Mesh(G.drop,new THREE.MeshLambertMaterial({color,emissive:color,emissiveIntensity:.9}));mesh.scale.setScalar(1+RAR[it.rarity].order*.12);g.add(mesh);const glow=glowSprite(color,1.1+RAR[it.rarity].order*.2,.5);g.add(glow);g.position.set(x,y,z);world.group.add(g);const a=Math.random()*TAU,sp=1.5+Math.random()*2;world.drops.push({item:itemId,n,source,x,y,z,vx:Math.cos(a)*sp,vy:3+Math.random()*2,vz:Math.sin(a)*sp,group:g,t:0,mesh,glow,collected:false,pickupDelay,blocked:false});}
function collectDrop(d){if(!d||d.collected)return false;if(!canPickup(d.item,d.n)){fullNotice();d.blocked=true;return false;}d.collected=true;addItem(d.item,d.n);if(d.source==='gather'){ensureCounters();S.counters.gather[d.item]=(S.counters.gather[d.item]||0)+d.n;}Sfx.pickup();lootFeed(item(d.item).icon+' +'+d.n+' '+item(d.item).name,rarityColor(d.item));burst(d.x,d.y,d.z,rarityColor(d.item),8,2,2,.5);checkTutorial();return true;}
function updateDrops(dt){for(let i=world.drops.length-1;i>=0;i--){const d=world.drops[i];if(!d||d.collected){world.group.remove(d.group);world.drops.splice(i,1);continue;}d.t+=dt;d.pickupDelay=Math.max(0,(d.pickupDelay||0)-dt);if(d.t<.5){d.vy-=12*dt;d.x+=d.vx*dt;d.y+=d.vy*dt;d.z+=d.vz*dt;if(d.y<.25){d.y=.25;d.vy*=-.35;d.vx*=.7;d.vz*=.7;}}else{const dx=player.x-d.x,dz=player.z-d.z,dist=Math.hypot(dx,dz)||1;const space=canPickup(d.item,d.n);d.blocked=!space;if(space&&d.pickupDelay<=0){const pull=Math.min(dist,(6+d.t*4)*dt);d.x+=dx/dist*pull;d.z+=dz/dist*pull;d.y+=(1-d.y)*Math.min(1,dt*6);if(dist<.7){if(collectDrop(d)){world.group.remove(d.group);world.drops.splice(i,1);continue;}}}else d.y+=(.3-d.y)*Math.min(1,dt*4);}const pulse=d.blocked?1+Math.sin(d.t*8)*.12:1;d.group.position.set(d.x,d.y+Math.sin(d.t*6)*.06,d.z);d.group.scale.setScalar(pulse);d.glow.material.color.set(d.blocked?0xff5a5f:rarityColor(d.item));d.mesh.rotation.y+=dt*3;d.mesh.rotation.x+=dt*2;}}
